package com.mixologyorderguard;

import com.mixologyorderguard.model.PotionType;

/**
 * Replicates one specific rule confirmed on the OSRS Wiki (Alembic/Agitator/Retort pages):
 * "If the machine is left-clicked, the first unprocessed potion in the player's inventory
 * will be input to the machine, regardless if it fulfills a current order." A plain
 * left-click carries no item information in its menu event at all - the game resolves the
 * item server-side - so to know what's actually about to be used, this has to independently
 * scan inventory order and apply the exact same "first one wins" rule the game does.
 */
final class FirstUnfinishedPotionFinder
{
	private FirstUnfinishedPotionFinder()
	{
	}

	/** @param inventoryItemIds item IDs in slot order (as returned by ItemContainer#getItems()); empty/negative entries for empty slots are fine. */
	static PotionType find(int[] inventoryItemIds)
	{
		for (int itemId : inventoryItemIds)
		{
			PotionType type = PotionType.fromUnfinishedItemId(itemId);
			if (type != null)
			{
				return type;
			}
		}
		return null;
	}
}

package com.mixologyorderguard;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("mixologyorderguard")
public interface MixologyOrderGuardConfig extends Config
{
	@ConfigItem(
		position = 0,
		keyName = "blockMismatchedPotions",
		name = "Block mismatched potions",
		description = "Stop you from using a potion on the Alembic, Agitator, or Retort when the result wouldn't match any of your current 3 orders. Turn off to just get the warning message below without anything actually being blocked"
	)
	default boolean blockMismatchedPotions()
	{
		return true;
	}

	@ConfigItem(
		position = 1,
		keyName = "showWarningMessage",
		name = "Show warning message",
		description = "Show a game message explaining why an action was blocked (or, with blocking off, why it would have been)"
	)
	default boolean showWarningMessage()
	{
		return true;
	}
}

package com.mixologyorderguard;

import com.google.inject.Provides;
import com.mixologyorderguard.model.PotionModifier;
import com.mixologyorderguard.model.PotionOrder;
import com.mixologyorderguard.model.PotionType;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.PostMenuSort;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

/**
 * Mastering Mixology has 3 machines - the Alembic, Agitator, and Retort - each of which
 * turns a held (unfinished) potion into one specific "modified" form (Crystalised,
 * Homogenous, or Concentrated respectively). Your 3 current orders each want a specific
 * potion in a specific modified form, so using the right potion on the wrong machine (or
 * the wrong potion on any machine) wastes it - it comes out as something none of your
 * orders need. This plugin catches that right as it's about to happen and blocks it - see
 * {@link OrderMatcher} for the one piece of logic that decides whether to.
 *
 * Handles both ways players actually interact with the stations, which turn out to behave
 * quite differently: explicitly using a held potion on a station (menu carries the exact
 * item used), and - what most players actually do - just left-clicking the station
 * directly, per the OSRS Wiki: "the first unprocessed potion in the player's inventory
 * will be input to the machine, regardless if it fulfills a current order." That second
 * path's menu click carries no item information at all (the game resolves it server-side),
 * so {@link #findFirstUnfinishedPotionInInventory()} independently replicates that exact
 * "first in inventory wins" rule to know what's actually about to be used.
 *
 * For that common left-click path, prevention happens two ways, one primary and one
 * fallback:
 * <ol>
 *   <li>{@link #onPostMenuSort} runs BEFORE the click, and on a mismatch swaps the
 *   station's left-click option with its own native "Check" option (see
 *   {@link StationMenuScan}) - so the click still does something real and safe instead of
 *   just silently failing. This is the same technique the "Brains Off Mixology" Hub plugin
 *   uses for its own (differently-scoped) station guard.</li>
 *   <li>{@link #onMenuOptionClicked} still reacts to the click itself too, via the
 *   standard {@code MenuOptionClicked#consume()} mechanism many "prevent misclicks" Hub
 *   plugins use - a safety net for whenever the swap didn't fire (no "Check" option was
 *   present to redirect to) and for the explicit item-use path, which has no menu entry to
 *   swap with in the first place.</li>
 * </ol>
 *
 * Neither layer touches a station that already holds a potion being processed - clicking
 * such a station repeatedly is how you speed up its processing, not how you insert a new
 * potion, so {@link #stationAlreadyHasPotion} exits both handlers early in that case
 * regardless of what's sitting in inventory.
 *
 * That "already occupied, leave it alone" check is itself a source of a genuine, narrow race:
 * during a fast spam-click burst - exactly the technique used to speed up processing - a
 * station finishing and auto-collecting can be immediately followed, within the same click or
 * the next one, by the real next potion actually being inserted, before this client's local
 * copy of that station's "potion" varbit has caught up to reflect the collection. Both
 * {@link #onPostMenuSort} and {@link #onMenuOptionClicked} read whatever value the client
 * currently has for that varbit, same as anything else in RuneLite would; there's no way for a
 * plugin to know a server response is already in flight but not yet applied, so a real insert
 * landing in that exact window can slip past both predictive layers undetected - the same class
 * of client/server latency race Brains Off Mixology's own {@code MixPrediction} exists to guard
 * against for its (differently-scoped) mixing-lever tracking. {@link #onVarbitChanged} is a
 * third, authoritative layer for exactly this gap: it can't undo an insert that already
 * happened, but the moment the station's potion varbit actually confirms one server-side, it
 * decodes the potion type directly from that confirmed value (no guessing from inventory) and,
 * if it doesn't match any order, immediately says so - so a slip-through is still caught and
 * flagged right away rather than going unnoticed until the wrong result comes out.
 *
 * Reads only public per-player game state already visible in the client (order varbits,
 * inventory contents, the menu being built). It doesn't perform any action for you, doesn't
 * automate anything, and doesn't touch any other interaction - only this one specific
 * wasted-potion mistake.
 */
@Slf4j
@PluginDescriptor(
	name = "Mixology Order Guard",
	description = "Blocks using a potion on the Alembic/Agitator/Retort at Mastering Mixology unless it actually matches one of your current potion orders",
	tags = {"mastering mixology", "mixology", "herblore", "potion", "order", "block"}
)
public class MixologyOrderGuardPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private MixologyOrderGuardConfig config;

	/**
	 * Last known value of each station's "potion" varbit, so {@link #onVarbitChanged} can
	 * tell "just went from empty to occupied" (a real insert worth checking) apart from any
	 * other change to that varbit. Indexed by {@link PotionModifier#ordinal()}.
	 */
	private final int[] lastKnownStationPotionVarbit = new int[PotionModifier.values().length];

	@Provides
	MixologyOrderGuardConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(MixologyOrderGuardConfig.class);
	}

	/**
	 * Primary prevention for the left-click path - see class javadoc. Runs before the click
	 * resolves, so a mismatch never even reaches {@link #onMenuOptionClicked}.
	 */
	@Subscribe
	public void onPostMenuSort(PostMenuSort event)
	{
		if (!config.blockMismatchedPotions() || client.isMenuOpen())
		{
			// isMenuOpen() means a right-click menu is already visibly on screen - only
			// swap while a menu is still being freshly built, not out from under one the
			// player is currently looking at.
			return;
		}

		Menu menu = client.getMenu();
		MenuEntry[] entries = menu.getMenuEntries();

		List<StationMenuScan.EntryInfo> entryInfos = new ArrayList<>(entries.length);
		for (int i = 0; i < entries.length; i++)
		{
			MenuEntry entry = entries[i];
			entryInfos.add(new StationMenuScan.EntryInfo(i, entry.getIdentifier(), entry.getType(), entry.getOption()));
		}

		StationMenuScan.Swap swap = StationMenuScan.findSwap(entryInfos);
		if (swap == null)
		{
			return;
		}

		if (stationAlreadyHasPotion(swap.getStation()))
		{
			// The station is already processing a potion - this click is just spam-clicking
			// it to speed that up, not inserting a new one, so leave the menu alone.
			return;
		}

		PotionType potionType = findFirstUnfinishedPotionInInventory();
		if (potionType == null)
		{
			return;
		}

		List<PotionOrder> orders = readCurrentOrders();
		if (OrderMatcher.matchesAnyOrder(orders, potionType, swap.getStation()))
		{
			return;
		}

		log.debug("Mixology Order Guard: redirecting left-click on {} to Check - {} doesn't match current orders",
			swap.getStation(), potionType);

		MenuEntry processingEntry = entries[swap.getProcessingIndex()];
		entries[swap.getProcessingIndex()] = entries[swap.getCheckIndex()];
		entries[swap.getCheckIndex()] = processingEntry;
		menu.setMenuEntries(entries);
	}

	/**
	 * Fallback for whenever the swap above couldn't happen (no native "Check" option was
	 * present to redirect to), and the only path at all for the explicit item-use
	 * interaction, which has no menu entries to swap with in the first place.
	 *
	 * ITEM_USE_ON_GAME_OBJECT (checked in the two methods below) is deprecated in favour of
	 * WIDGET_TARGET_ON_GAME_OBJECT but still checked defensively alongside it, matching how
	 * other Hub plugins handle this same menu action pair - see class javadoc.
	 */
	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (!config.blockMismatchedPotions() && !config.showWarningMessage())
		{
			return;
		}

		PotionModifier modifier = resolveStationModifier(event);
		if (modifier == null)
		{
			// Not an interaction with one of the 3 finishing stations at all (includes
			// Examine, which uses its own separate menu action and is never matched here).
			return;
		}

		log.debug("Mixology Order Guard: station interaction detected - action={}, objectId={}, itemId={}, resolved station={}",
			event.getMenuAction(), event.getId(), event.getItemId(), modifier);

		if (stationAlreadyHasPotion(modifier))
		{
			// Same reasoning as onPostMenuSort - a click on a station that already holds a
			// potion is speeding up its processing, not inserting a new (possibly mismatched)
			// one, so there's nothing to check here.
			return;
		}

		PotionType potionType = resolvePotionType(event);
		if (potionType == null)
		{
			log.debug("Mixology Order Guard: couldn't determine which potion is being used - allowing through");
			return;
		}

		List<PotionOrder> orders = readCurrentOrders();
		log.debug("Mixology Order Guard: about to use {} on {} - current orders: {}", potionType, modifier, orders);

		if (OrderMatcher.matchesAnyOrder(orders, potionType, modifier))
		{
			return;
		}

		if (config.showWarningMessage())
		{
			sendWarning(potionType, modifier);
		}

		if (config.blockMismatchedPotions())
		{
			event.consume();
		}
	}

	/**
	 * Authoritative safety net for the race described in the class javadoc - reacts to the
	 * server actually confirming a potion just landed in a station, which the two predictive
	 * layers above can occasionally miss during a fast spam-click burst. Can't block or undo
	 * the insert (it's already happened by the time this fires), but decodes the potion type
	 * directly from the confirmed varbit value and warns immediately if it's a mismatch, so
	 * it doesn't go unnoticed.
	 */
	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		PotionModifier station = PotionModifier.fromPotionVarbitId(event.getVarbitId());
		if (station == null)
		{
			return;
		}

		int previousValue = lastKnownStationPotionVarbit[station.ordinal()];
		int newValue = event.getValue();
		lastKnownStationPotionVarbit[station.ordinal()] = newValue;

		if (!config.showWarningMessage())
		{
			return;
		}

		if (previousValue != 0 || newValue == 0)
		{
			// Only interested in empty -> occupied, the moment a potion is actually inserted.
			// Any other transition (already occupied, or just emptied by a collect) isn't one.
			return;
		}

		PotionType insertedType = PotionType.fromVarbitIndex(newValue - 1);
		if (insertedType == null)
		{
			return;
		}

		List<PotionOrder> orders = readCurrentOrders();
		if (OrderMatcher.matchesAnyOrder(orders, insertedType, station))
		{
			return;
		}

		log.debug("Mixology Order Guard: confirmed mismatch already in the {} - {} doesn't match current orders",
			station, insertedType);
		sendAlreadyInsertedWarning(insertedType, station);
	}

	/** Any interaction that could plausibly feed a potion into one of the 3 stations - not just the explicit "use item on object" one most players don't actually use. */
	@SuppressWarnings("deprecation") // see onMenuOptionClicked
	private static PotionModifier resolveStationModifier(MenuOptionClicked event)
	{
		switch (event.getMenuAction())
		{
			case ITEM_USE_ON_GAME_OBJECT:
			case WIDGET_TARGET_ON_GAME_OBJECT:
				return PotionModifier.fromStationObjectId(event.getId());
			case GAME_OBJECT_FIRST_OPTION:
			case GAME_OBJECT_SECOND_OPTION:
			case GAME_OBJECT_THIRD_OPTION:
			case GAME_OBJECT_FOURTH_OPTION:
			case GAME_OBJECT_FIFTH_OPTION:
				if (isSafeStationOption(event.getMenuOption()))
				{
					// Either the native "Check" option, or the one onPostMenuSort just
					// swapped in to replace a mismatched processing click - either way,
					// nothing is actually being processed here, so there's nothing to block.
					return null;
				}
				return PotionModifier.fromStationObjectId(event.getId());
			default:
				return null;
		}
	}

	private static boolean isSafeStationOption(String option)
	{
		return "Check".equalsIgnoreCase(option) || "Examine".equalsIgnoreCase(option);
	}

	@SuppressWarnings("deprecation") // see onMenuOptionClicked
	private PotionType resolvePotionType(MenuOptionClicked event)
	{
		MenuAction action = event.getMenuAction();
		if (action == MenuAction.ITEM_USE_ON_GAME_OBJECT || action == MenuAction.WIDGET_TARGET_ON_GAME_OBJECT)
		{
			// The player explicitly picked this potion - trust that over guessing.
			return PotionType.fromUnfinishedItemId(event.getItemId());
		}

		// A plain click on the station itself carries no item info - the game resolves it
		// server-side by taking the first unprocessed potion in inventory (confirmed on
		// the wiki), so independently apply that same rule to know what's about to happen.
		return findFirstUnfinishedPotionInInventory();
	}

	/**
	 * True while {@code station} already holds a potion being processed - each station has
	 * its own "potion" varbit for exactly this, encoded 0 = empty, non-zero = a potion type
	 * present (same convention as the order varbits). Confirmed against Brains Off Mixology's
	 * {@code Station.getPotionVarbit()}/{@code activeStations} handling - see class javadoc.
	 */
	private boolean stationAlreadyHasPotion(PotionModifier station)
	{
		return client.getVarbitValue(station.getPotionVarbitId()) != 0;
	}

	private PotionType findFirstUnfinishedPotionInInventory()
	{
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory == null)
		{
			return null;
		}

		Item[] items = inventory.getItems();
		int[] itemIds = new int[items.length];
		for (int i = 0; i < items.length; i++)
		{
			itemIds[i] = items[i] == null ? -1 : items[i].getId();
		}
		return FirstUnfinishedPotionFinder.find(itemIds);
	}

	private List<PotionOrder> readCurrentOrders()
	{
		List<PotionOrder> orders = new ArrayList<>(3);
		addOrderIfPresent(orders, VarbitID.MM_LAB_ORDER_1_TYPE, VarbitID.MM_LAB_ORDER_1_MODIFIER);
		addOrderIfPresent(orders, VarbitID.MM_LAB_ORDER_2_TYPE, VarbitID.MM_LAB_ORDER_2_MODIFIER);
		addOrderIfPresent(orders, VarbitID.MM_LAB_ORDER_3_TYPE, VarbitID.MM_LAB_ORDER_3_MODIFIER);
		return orders;
	}

	private void addOrderIfPresent(List<PotionOrder> orders, int typeVarbitId, int modifierVarbitId)
	{
		// The game encodes "no order in this slot" as 0, with real values starting at 1 -
		// same -1 offset convention as the reference implementation this was verified
		// against (see class javadoc).
		PotionType type = PotionType.fromVarbitIndex(client.getVarbitValue(typeVarbitId) - 1);
		PotionModifier modifier = PotionModifier.fromVarbitIndex(client.getVarbitValue(modifierVarbitId) - 1);

		if (type != null && modifier != null)
		{
			orders.add(new PotionOrder(type, modifier));
		}
	}

	private void sendWarning(PotionType potionType, PotionModifier modifier)
	{
		String suffix = config.blockMismatchedPotions() ? " - blocked." : ".";
		String message = "<col=ff0000>" + potionType.getDisplayName() + "</col> on the " + modifier.getStationName()
			+ " doesn't match any of your current orders" + suffix;
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null);
	}

	private void sendAlreadyInsertedWarning(PotionType potionType, PotionModifier modifier)
	{
		String message = "<col=ff0000>" + potionType.getDisplayName() + "</col> was just put in the "
			+ modifier.getStationName() + " but doesn't match any of your current orders - it's being wasted!";
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null);
	}
}

package com.mixologyorderguard;

import com.mixologyorderguard.model.PotionModifier;
import com.mixologyorderguard.model.PotionOrder;
import com.mixologyorderguard.model.PotionType;
import java.util.List;

/**
 * The one decision this whole plugin makes: does using this potion on this station actually
 * produce something one of the current orders wants? Deliberately the only piece of "should
 * I block this?" logic, kept pure and separate from the menu-event plumbing so it can be
 * tested directly rather than only by clicking around in a real client.
 *
 * Doesn't track which orders are already fulfilled - only whether (potionType, modifier)
 * appears in the current 3 slots at all. A blocking plugin should be biased toward NOT
 * blocking when uncertain: the cost of a false "allowed through" is a wasted potion (the
 * same mistake the player would've made without this plugin installed), but the cost of a
 * false block is actively preventing something the player correctly intended to do. Given
 * that asymmetry, deliberately not replicating fulfilled-order tracking (a real source of
 * subtle bugs in similar plugins) in exchange for a strictly simpler, easier-to-trust check.
 */
final class OrderMatcher
{
	private OrderMatcher()
	{
	}

	static boolean matchesAnyOrder(List<PotionOrder> orders, PotionType potionType, PotionModifier modifier)
	{
		if (potionType == null || modifier == null)
		{
			return true;
		}

		for (PotionOrder order : orders)
		{
			if (order.getPotionType() == potionType && order.getPotionModifier() == modifier)
			{
				return true;
			}
		}
		return false;
	}
}

package com.mixologyorderguard;

import com.mixologyorderguard.model.PotionModifier;
import java.util.List;
import net.runelite.api.MenuAction;

/**
 * Finds a swap that would make a plain left-click on a station safely trigger its native
 * "Check" option instead of processing a potion - the technique used by the "Brains Off
 * Mixology" Hub plugin's {@code StationMenuGuard} (github.com/giuqoob/osrs-plugin-brains-off-mixology),
 * adapted here for order-matching instead of that plugin's own batch-sequence guard. Redirecting
 * the click this way (via {@code PostMenuSort}, before the click resolves) reads better than
 * silently consuming the click after the fact: the player still gets a real, safe response
 * instead of nothing visibly happening.
 *
 * Pure and RuneLite-Client-free by design - takes plain {@link EntryInfo} tuples rather
 * than real {@code MenuEntry} objects, so the actual decision logic is testable without a
 * live client. Simplified relative to the reference implementation: that one groups entries
 * by object + scene coordinates to handle multiple instances of the same object type on
 * screen at once, which doesn't apply here since each of the 3 stations is a singleton in
 * the lab room.
 *
 * The real client's menu for a station lists "Check" *before* the processing option (e.g.
 * {@code [..., "Check", "Concentrate-potion"]} for the Retort, confirmed from a live debug
 * log) - {@link #findSwap} is written to not assume either ordering, after an earlier
 * position-dependent version silently never found a swap because it happened to assume the
 * opposite of what the real client actually does.
 */
final class StationMenuScan
{
	private StationMenuScan()
	{
	}

	static final class EntryInfo
	{
		final int index;
		final int objectId;
		final MenuAction type;
		final String option;

		EntryInfo(int index, int objectId, MenuAction type, String option)
		{
			this.index = index;
			this.objectId = objectId;
			this.type = type;
			this.option = option;
		}
	}

	static final class Swap
	{
		private final PotionModifier station;
		private final int processingIndex;
		private final int checkIndex;

		private Swap(PotionModifier station, int processingIndex, int checkIndex)
		{
			this.station = station;
			this.processingIndex = processingIndex;
			this.checkIndex = checkIndex;
		}

		PotionModifier getStation()
		{
			return station;
		}

		int getProcessingIndex()
		{
			return processingIndex;
		}

		int getCheckIndex()
		{
			return checkIndex;
		}
	}

	/**
	 * Null if there's no processing option for one of our 3 stations in this menu, or no
	 * "Check" option to safely redirect it to. Two passes rather than one, deliberately: the
	 * real client's menu lists "Check" *before* the processing option (confirmed live - see
	 * class javadoc), so a single left-to-right pass that only starts looking for "Check"
	 * once it's already seen the processing entry would silently never find it. Finding the
	 * processing entry first, then searching independently of position for its station's
	 * "Check" entry, works regardless of which order the client happens to list them in.
	 */
	static Swap findSwap(List<EntryInfo> entries)
	{
		PotionModifier station = null;
		int processingIndex = -1;
		for (EntryInfo entry : entries)
		{
			if (entry.type != MenuAction.GAME_OBJECT_FIRST_OPTION)
			{
				continue;
			}
			PotionModifier candidate = PotionModifier.fromStationObjectId(entry.objectId);
			if (candidate != null)
			{
				station = candidate;
				processingIndex = entry.index;
				break;
			}
		}
		if (station == null)
		{
			return null;
		}

		int checkIndex = -1;
		for (EntryInfo entry : entries)
		{
			if ("Check".equalsIgnoreCase(entry.option) && PotionModifier.fromStationObjectId(entry.objectId) == station)
			{
				checkIndex = entry.index;
				break;
			}
		}
		if (checkIndex < 0)
		{
			return null;
		}

		return new Swap(station, processingIndex, checkIndex);
	}
}

package com.mixologyorderguard.model;

import net.runelite.api.gameval.ObjectID;
import net.runelite.api.gameval.VarbitID;

/**
 * Which finishing station a potion needs to be used on, and what it becomes there. Station
 * object IDs and the varbit encoding (index 0=Homogenous, 1=Concentrated, 2=Crystalised)
 * confirmed against the "Mastering Mixology" Hub plugin's source
 * (github.com/hex-agon/mastering-mixology) - see {@code PotionModifier.java}/{@code AlchemyObject.java} there.
 *
 * Each station also has its own "potion" varbit (confirmed against Brains Off Mixology's
 * {@code Station.getPotionVarbit()}) that's non-zero exactly while that station already holds
 * a potion being processed - needed to tell "inserting a new potion" apart from "spam-clicking
 * an already-loaded station to speed up its processing," which look identical at the menu-click
 * level but must never both be treated as an insert.
 */
public enum PotionModifier
{
	HOMOGENOUS(ObjectID.MM_LAB_MACHINE_AGITATOR, VarbitID.MM_LAB_AGITATOR_POTION, "Agitator"),
	CONCENTRATED(ObjectID.MM_LAB_MACHINE_RETORT, VarbitID.MM_LAB_RETORT_POTION, "Retort"),
	CRYSTALISED(ObjectID.MM_LAB_MACHINE_ALEMBIC, VarbitID.MM_LAB_ALEMBIC_POTION, "Alembic");

	private static final PotionModifier[] VALUES = values();

	private final int stationObjectId;
	private final int potionVarbitId;
	private final String stationName;

	PotionModifier(int stationObjectId, int potionVarbitId, String stationName)
	{
