package com.mixologyorderguard.model;

import java.util.HashMap;
import java.util.Map;
import net.runelite.api.gameval.ItemID;

/**
 * The 10 base potions Mastering Mixology can produce, and the item ID for their unfinished
 * (pre-station) form - that's the form you'd actually be holding when using one on the
 * Alembic/Agitator/Retort. Item IDs and varbit encoding (declaration order = varbit index)
 * confirmed against the "Mastering Mixology" Hub plugin's source
 * (github.com/hex-agon/mastering-mixology) - see {@code PotionType.java} there.
 */
public enum PotionType
{
	MAMMOTH_MIGHT_MIX(ItemID.MM_POTION_MMM_UNFINISHED, "Mammoth-might mix"),
	MYSTIC_MANA_AMALGAM(ItemID.MM_POTION_MMA_UNFINISHED, "Mystic mana amalgam"),
	MARLEYS_MOONLIGHT(ItemID.MM_POTION_MML_UNFINISHED, "Marley's moonlight"),
	ALCO_AUGMENTATOR(ItemID.MM_POTION_AAA_UNFINISHED, "Alco-augmentator"),
	AZURE_AURA_MIX(ItemID.MM_POTION_AAM_UNFINISHED, "Azure aura mix"),
	AQUALUX_AMALGAM(ItemID.MM_POTION_AAL_UNFINISHED, "Aqualux amalgam"),
	LIPLACK_LIQUOR(ItemID.MM_POTION_LLL_UNFINISHED, "Liplack liquor"),
	MEGALITE_LIQUID(ItemID.MM_POTION_LLM_UNFINISHED, "Megalite liquid"),
	ANTI_LEECH_LOTION(ItemID.MM_POTION_LLA_UNFINISHED, "Anti-leech lotion"),
	MIXALOT(ItemID.MM_POTION_MAL_UNFINISHED, "Mixalot");

	private static final PotionType[] VALUES = values();
	private static final Map<Integer, PotionType> BY_UNFINISHED_ITEM_ID = new HashMap<>();

	static
	{
		for (PotionType type : VALUES)
		{
			BY_UNFINISHED_ITEM_ID.put(type.unfinishedItemId, type);
		}
	}

	private final int unfinishedItemId;
	private final String displayName;

	PotionType(int unfinishedItemId, String displayName)
	{
		this.unfinishedItemId = unfinishedItemId;
		this.displayName = displayName;
	}

	public int getUnfinishedItemId()
	{
		return unfinishedItemId;
	}

	public String getDisplayName()
	{
		return displayName;
	}

	public static PotionType fromVarbitIndex(int index)
	{
		return index >= 0 && index < VALUES.length ? VALUES[index] : null;
	}

	/** Null if this isn't the unfinished form of one of the 10 potions (e.g. it's an unrelated item, or an already-finished potion). */
	public static PotionType fromUnfinishedItemId(int itemId)
	{
		return BY_UNFINISHED_ITEM_ID.get(itemId);
	}
}

package com.mixologyorderguard;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import com.mixologyorderguard.model.PotionType;
import org.junit.Test;

/**
 * Covers the rule confirmed on the wiki: a plain left-click on a station uses "the first
 * unprocessed potion in the player's inventory", by slot order - not the highest-value one,
 * not one matching an order, just the first one physically in the inventory grid.
 */
public class FirstUnfinishedPotionFinderTest
{
	@Test
	public void findsTheOnlyUnfinishedPotion()
	{
		int[] inventory = {995, PotionType.MIXALOT.getUnfinishedItemId(), -1};
		assertEquals(PotionType.MIXALOT, FirstUnfinishedPotionFinder.find(inventory));
	}

	@Test
	public void picksTheEarliestSlotNotTheBestOrder()
	{
		int[] inventory = {
			PotionType.LIPLACK_LIQUOR.getUnfinishedItemId(),
			PotionType.MIXALOT.getUnfinishedItemId()
		};
		assertEquals(PotionType.LIPLACK_LIQUOR, FirstUnfinishedPotionFinder.find(inventory));
	}

	@Test
	public void ignoresFinishedPotionsAndUnrelatedItems()
	{
		int[] inventory = {995, 1511, PotionType.AQUALUX_AMALGAM.getUnfinishedItemId()};
		assertEquals(PotionType.AQUALUX_AMALGAM, FirstUnfinishedPotionFinder.find(inventory));
	}

	@Test
	public void returnsNullWhenNoUnfinishedPotionIsHeld()
	{
		int[] inventory = {995, 1511, -1, 0};
		assertNull(FirstUnfinishedPotionFinder.find(inventory));
	}

	@Test
	public void returnsNullForEmptyInventory()
	{
		assertNull(FirstUnfinishedPotionFinder.find(new int[0]));
	}
}

