import com.mixologyorderguard.model.PotionType;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

public class OrderMatcherTest
{
	@Test
	public void matchesWhenExactTypeAndModifierAreOrdered()
	{
		List<PotionOrder> orders = Collections.singletonList(
			new PotionOrder(PotionType.MIXALOT, PotionModifier.CONCENTRATED));

		assertTrue(OrderMatcher.matchesAnyOrder(orders, PotionType.MIXALOT, PotionModifier.CONCENTRATED));
	}

	@Test
	public void doesNotMatchRightPotionWrongMachine()
	{
		// Ordered Crystalised, but about to be used on the Agitator (-> Homogenous).
		List<PotionOrder> orders = Collections.singletonList(
			new PotionOrder(PotionType.MAMMOTH_MIGHT_MIX, PotionModifier.CRYSTALISED));

		assertFalse(OrderMatcher.matchesAnyOrder(orders, PotionType.MAMMOTH_MIGHT_MIX, PotionModifier.HOMOGENOUS));
	}

	@Test
	public void doesNotMatchWrongPotionRightMachine()
	{
		List<PotionOrder> orders = Collections.singletonList(
			new PotionOrder(PotionType.MIXALOT, PotionModifier.HOMOGENOUS));

		assertFalse(OrderMatcher.matchesAnyOrder(orders, PotionType.LIPLACK_LIQUOR, PotionModifier.HOMOGENOUS));
	}

	@Test
	public void matchesAnyOfTheThreeCurrentOrders()
	{
		List<PotionOrder> orders = Arrays.asList(
			new PotionOrder(PotionType.MIXALOT, PotionModifier.HOMOGENOUS),
			new PotionOrder(PotionType.LIPLACK_LIQUOR, PotionModifier.CONCENTRATED),
			new PotionOrder(PotionType.AQUALUX_AMALGAM, PotionModifier.CRYSTALISED));

		assertTrue(OrderMatcher.matchesAnyOrder(orders, PotionType.LIPLACK_LIQUOR, PotionModifier.CONCENTRATED));
	}

	@Test
	public void noMatchWhenOrderListIsEmpty()
	{
		assertFalse(OrderMatcher.matchesAnyOrder(Collections.emptyList(), PotionType.MIXALOT, PotionModifier.CONCENTRATED));
	}

	@Test
	public void failsOpenWhenPotionTypeIsUnknown()
	{
		List<PotionOrder> orders = Collections.singletonList(
			new PotionOrder(PotionType.MIXALOT, PotionModifier.CONCENTRATED));

		assertTrue(OrderMatcher.matchesAnyOrder(orders, null, PotionModifier.CONCENTRATED));
	}

	@Test
	public void failsOpenWhenModifierIsUnknown()
	{
		List<PotionOrder> orders = Collections.singletonList(
			new PotionOrder(PotionType.MIXALOT, PotionModifier.CONCENTRATED));

		assertTrue(OrderMatcher.matchesAnyOrder(orders, PotionType.MIXALOT, null));
	}
}

package com.mixologyorderguard;

import static org.junit.Assert.assertEquals;
