import net.runelite.api.MenuAction;
import org.junit.Test;

public class StationMenuScanTest
{
	private static final int ALEMBIC_ID = PotionModifier.CRYSTALISED.getStationObjectId();

	private static StationMenuScan.EntryInfo entry(int index, int objectId, MenuAction type, String option)
	{
		return new StationMenuScan.EntryInfo(index, objectId, type, option);
	}

	@Test
	public void findsTheSwapWhenBothProcessingAndCheckArePresent()
	{
		List<StationMenuScan.EntryInfo> entries = Arrays.asList(
			entry(0, ALEMBIC_ID, MenuAction.GAME_OBJECT_FIRST_OPTION, "Crystallise"),
			entry(1, ALEMBIC_ID, MenuAction.GAME_OBJECT_SECOND_OPTION, "Check"),
			entry(2, ALEMBIC_ID, MenuAction.EXAMINE_OBJECT, "Examine"));

		StationMenuScan.Swap swap = StationMenuScan.findSwap(entries);

		assertEquals(PotionModifier.CRYSTALISED, swap.getStation());
		assertEquals(0, swap.getProcessingIndex());
		assertEquals(1, swap.getCheckIndex());
	}

	@Test
	public void findsTheSwapWhenCheckComesBeforeProcessingInTheMenu()
	{
		// This is the order the real client actually uses (confirmed from a live debug log
		// dump: "[..., Check, Concentrate-potion]") - an earlier version of findSwap only
		// ever looked for "Check" after it had already seen the processing entry, so it
		// silently never matched this ordering. See class javadoc.
		List<StationMenuScan.EntryInfo> entries = Arrays.asList(
			entry(0, ALEMBIC_ID, MenuAction.CANCEL, "Cancel"),
			entry(1, ALEMBIC_ID, MenuAction.EXAMINE_OBJECT, "Examine"),
			entry(2, ALEMBIC_ID, MenuAction.GAME_OBJECT_THIRD_OPTION, "Check"),
			entry(3, ALEMBIC_ID, MenuAction.GAME_OBJECT_FIRST_OPTION, "Crystallise"));

		StationMenuScan.Swap swap = StationMenuScan.findSwap(entries);

		assertEquals(PotionModifier.CRYSTALISED, swap.getStation());
		assertEquals(3, swap.getProcessingIndex());
		assertEquals(2, swap.getCheckIndex());
	}

	@Test
	public void findsNothingWhenMenuIsForAnUnrelatedObject()
	{
		List<StationMenuScan.EntryInfo> entries = Collections.singletonList(
			entry(0, 12345, MenuAction.GAME_OBJECT_FIRST_OPTION, "Open"));

		assertNull(StationMenuScan.findSwap(entries));
	}

	@Test
	public void findsNothingWhenThereIsNoCheckOptionToRedirectTo()
	{
		List<StationMenuScan.EntryInfo> entries = Collections.singletonList(
			entry(0, ALEMBIC_ID, MenuAction.GAME_OBJECT_FIRST_OPTION, "Crystallise"));

		assertNull(StationMenuScan.findSwap(entries));
	}

	@Test
	public void findsNothingWhenThereIsNoProcessingOption()
	{
		List<StationMenuScan.EntryInfo> entries = Collections.singletonList(
			entry(0, ALEMBIC_ID, MenuAction.GAME_OBJECT_SECOND_OPTION, "Check"));

		assertNull(StationMenuScan.findSwap(entries));
	}

	@Test
	public void ignoresACheckOptionBelongingToADifferentStation()
	{
		int agitatorId = PotionModifier.HOMOGENOUS.getStationObjectId();
		List<StationMenuScan.EntryInfo> entries = Arrays.asList(
			entry(0, ALEMBIC_ID, MenuAction.GAME_OBJECT_FIRST_OPTION, "Crystallise"),
			entry(1, agitatorId, MenuAction.GAME_OBJECT_SECOND_OPTION, "Check"));

		assertNull(StationMenuScan.findSwap(entries));
	}
}

package com.mixologyorderguard.model;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import org.junit.Test;

/**
 * Locks in the varbit-index -> enum mapping so a future reordering of either enum's
 * declaration (which would silently change what index each value maps to) fails loudly
 * here instead of silently mismatching potions in the live client.
 */
public class VarbitMappingTest
{
	@Test
	public void potionModifierIndexOrderMatchesGameEncoding()
	{
		assertEquals(PotionModifier.HOMOGENOUS, PotionModifier.fromVarbitIndex(0));
		assertEquals(PotionModifier.CONCENTRATED, PotionModifier.fromVarbitIndex(1));
		assertEquals(PotionModifier.CRYSTALISED, PotionModifier.fromVarbitIndex(2));
		assertNull(PotionModifier.fromVarbitIndex(-1));
		assertNull(PotionModifier.fromVarbitIndex(3));
	}

	@Test
	public void potionTypeIndexOrderMatchesGameEncoding()
	{
		assertEquals(PotionType.MAMMOTH_MIGHT_MIX, PotionType.fromVarbitIndex(0));
		assertEquals(PotionType.MYSTIC_MANA_AMALGAM, PotionType.fromVarbitIndex(1));
		assertEquals(PotionType.MARLEYS_MOONLIGHT, PotionType.fromVarbitIndex(2));
		assertEquals(PotionType.ALCO_AUGMENTATOR, PotionType.fromVarbitIndex(3));
		assertEquals(PotionType.AZURE_AURA_MIX, PotionType.fromVarbitIndex(4));
		assertEquals(PotionType.AQUALUX_AMALGAM, PotionType.fromVarbitIndex(5));
		assertEquals(PotionType.LIPLACK_LIQUOR, PotionType.fromVarbitIndex(6));
		assertEquals(PotionType.MEGALITE_LIQUID, PotionType.fromVarbitIndex(7));
		assertEquals(PotionType.ANTI_LEECH_LOTION, PotionType.fromVarbitIndex(8));
		assertEquals(PotionType.MIXALOT, PotionType.fromVarbitIndex(9));
		assertNull(PotionType.fromVarbitIndex(-1));
		assertNull(PotionType.fromVarbitIndex(10));
	}

	@Test
	public void everyPotionModifierMapsBackToItsOwnStation()
	{
		for (PotionModifier modifier : PotionModifier.values())
		{
			assertEquals(modifier, PotionModifier.fromStationObjectId(modifier.getStationObjectId()));
		}
	}

	@Test
	public void unknownStationObjectIdReturnsNull()
	{
		assertNull(PotionModifier.fromStationObjectId(-1));
	}

	@Test
	public void everyPotionTypeMapsBackFromItsOwnUnfinishedItemId()
	{
		for (PotionType type : PotionType.values())
		{
			assertEquals(type, PotionType.fromUnfinishedItemId(type.getUnfinishedItemId()));
		}
	}

	@Test
	public void unknownItemIdReturnsNull()
	{
		assertNull(PotionType.fromUnfinishedItemId(-1));
	}
}
